definition.script:
// Verify both ephemeral Build Agent adapters across the Socket Proxy seam
stage('Node.js 26 LTS (node-caged) Build Agent') {
    node('node26') {
        sh '''
            echo "=== Node.js Build Agent ==="
            java -version
            node --version
            npm --version
            node -e "console.log('V8 heap limit (MB):', Math.round(require('v8').getHeapStatistics().heap_size_limit / 1024 / 1024))"
        '''
    }
}

stage('C# / .NET 10 SDK Build Agent') {
    node('net10') {
        sh '''
            echo "=== .NET SDK Build Agent ==="
            java -version
            dotnet --version
            dotnet --list-sdks
            echo "=== Ephemeral DB Sidecar / Testcontainers Readiness (via proxy1:2375) ==="
            docker version --format 'Client: {{.Client.Version}} / Server: {{.Server.Version}}'
            docker run --rm --network jenkins_jenkins-net postgres:18-alpine postgres --version
        '''
    }
}
